"use client";

import { RadioGroup as RadioGroupPrimitive } from "@base-ui/react/radio-group";
import { Radio as RadioPrimitive } from "@base-ui/react/radio";

import { cn } from "@/lib/utils";
import { controlChecked, focusRing } from "./_shared";

type WithClassName<P> = Omit<P, "className"> & { className?: string };

/** Ink mail RadioGroup: a column of choices with 0.75rem between them. */
function RadioGroup({
  className,
  ...props
}: WithClassName<RadioGroupPrimitive.Props>) {
  return (
    <RadioGroupPrimitive
      data-slot="radio-group"
      className={cn("grid gap-3", className)}
      {...props}
    />
  );
}
RadioGroup.displayName = "RadioGroup";

/**
 * Ink mail RadioGroupItem: a 1rem circle with a grey edge on the black page.
 * Chosen, it fills with the primary button's off-white and holds a small
 * black dot at its centre.
 */
function RadioGroupItem({
  className,
  ...props
}: WithClassName<RadioPrimitive.Root.Props>) {
  return (
    <RadioPrimitive.Root
      data-slot="radio-group-item"
      className={cn(
        "inline-flex items-center justify-center aspect-square size-4 shrink-0 rounded-full border border-(--control) bg-transparent",
        "transition-[background-color,border-color] duration-fast ease-out",
        focusRing,
        "data-[disabled]:cursor-not-allowed data-[disabled]:border-(--line-strong)",
        controlChecked,
        className,
      )}
      {...props}
    >
      <RadioPrimitive.Indicator
        data-slot="radio-group-indicator"
        className="flex size-full items-center justify-center"
      >
        <span className="block size-1.5 rounded-full bg-primary-foreground" />
      </RadioPrimitive.Indicator>
    </RadioPrimitive.Root>
  );
}
RadioGroupItem.displayName = "RadioGroupItem";

export { RadioGroup, RadioGroupItem };
